21	    // Close the browser context to ensure complete isolation between tests.
22	    // This releases browser instances, network connections, and other resources.
23	    await context.close();
24	    // Wait 500ms to allow async cleanup operations to complete.
25	    // Without this delay, running 6+ tests in sequence causes flaky failures
26	    // due to resource exhaustion (network connections, file descriptors, etc).
27	    // This timing issue manifests as timeouts when loading article pages.
28	    // This will be investigated and fixed later.
29	    await new Promise(resolve => setTimeout(resolve, 500));
30	  });
31	
32	  test('should create a new article', async ({ page }) => {
33	    const article = generateUniqueArticle();
34	
35	    await createArticle(page, article);
36	
37	    // Should be on article page
38	    await expect(page).toHaveURL(/\/article\/.+/);
39	
