2	import { register, generateUniqueUser } from './auth';
3	import { registerUserViaAPI, createManyArticles as createManyArticlesViaAPI } from './api';
4	import { API_MODE } from './config';
5	
6	export interface UserCredentials {
7	  username: string;
8	  email: string;
9	  password: string;
10	}
11	
12	/**
13	 * Create a user in an isolated browser context (for non-API mode)
14	 * or via API (default).
15	 */
16	export async function createUserInIsolation(
17	  browser: Browser,
18	  user?: UserCredentials,
19	): Promise<UserCredentials> {
20	  const u = user || generateUniqueUser();
21	  const ctx = await browser.newContext();
22	  const page = await ctx.newPage();
23	  await register(page, u.username, u.email, u.password);
24	  await ctx.close();
25	  return u;
26	}
27	
28	/**
29	 * Create many articles for pagination tests.
30	 * Uses API when available (fast), falls back to form submissions.
31	 */
32	export async function createManyArticles(
33	  page: Page,
34	  count: number,
35	  tag: string = 'paginationtest',
36	  request?: APIRequestContext,
37	  token?: string,
38	): Promise<void> {
39	  if (API_MODE && request && token) {
40	    await createManyArticlesViaAPI(request, token, count, tag);
41	  } else {
42	    // Form-based: fill out the editor for each article
43	    const uniqueId = `${Date.now()}${Math.random().toString(36).substring(2, 8)}`;
44	    for (let i = 0; i < count; i++) {
45	      await page.goto('/editor', { waitUntil: 'load' });
46	      await page.fill('input[name="title"]', `Test Article ${uniqueId} Number ${i}`);
47	      await page.fill('input[name="description"]', `Description for test article ${i}`);
48	      await page.fill('textarea[name="body"]', `Body content for test article ${i}. Created with ID ${uniqueId}.`);
49	      await page.fill('input[placeholder="Enter tags"]', tag);
